namespace ErpSimulator.Domain.Invoices;

/// <summary>
/// The ERP's cancellation of an invoice number (the cancellations table). Unique per invoice number: the same cancellation
/// sent again gets this record back instead of a new one.
/// </summary>
public sealed class ErpCancellation
{
    public long Id { get; set; }

    /// <summary>Generated by the database from a sequence, e.g. IPT-00000042.</summary>
    public string CancelReference { get; set; } = null!;

    public required string InvoiceNumber { get; set; }

    public DateTimeOffset CancelledAt { get; set; }
}
